code.snippet:
body.t-zen section { padding-top: 110px; }
body.t-zen .hero h1 { font-weight: 400; letter-spacing: 12px; }
body.t-zen .hero h1::after { content: ""; display: block; width: 1px; height: 52px; background: var(--text); margin-top: 22px; opacity: .5; }
body.t-zen .tagline { color: var(--accent); font-weight: 400; letter-spacing: 6px; }
body.t-zen .tagline::before { content: "【"; color: var(--accent-2); }
body.t-zen .tagline::after { content: "】"; color: var(--accent-2); }
body.t-zen .hero-badge { background: transparent; border: none; border-left: 2px solid var(--accent-2); border-radius: 0; padding: 4px 12px; }
body.t-zen .hero-badge i { background: var(--accent-2); border-radius: 0; width: 6px; height: 6px; animation: none; }
body.t-zen .section-title { font-weight: 400; letter-spacing: 8px; }
body.t-zen .section-title::before { content: ""; display: block; width: 34px; height: 2px; background: var(--accent-2); margin-bottom: 18px; }
body.t-zen .section-tag { display: none; }
body.t-zen .card { border: none; border-top: 1px solid var(--border); padding: 26px 2px 20px; background: transparent; }
body.t-zen .card:hover { border-top-color: var(--text); box-shadow: none; }
body.t-zen .card.featured { border-top: 2px solid var(--accent-2); }
body.t-zen .card.featured::before { content: "特"; background: var(--accent-2); border-radius: 0; padding: 3px 9px; }
